     <p v-if="rightStore" class="secondary">按已配置功能列出所选门店的允许 / 拒绝结果；未列出的功能未获授权。</p>
     <el-table :data="visibleRights" empty-text="当前端没有匹配的已授权功能"><el-table-column label="功能" min-width="180"><template #default="{row}">{{permissionLabel(row.code)}}</template></el-table-column><el-table-column v-if="rightStore" label="结果" width="90"><template #default="{row}"><el-tag :type="row.stores.some(s=>s.id===rightStore)?'success':'danger'">{{row.stores.some(s=>s.id===rightStore)?'允许':'拒绝'}}</el-tag></template></el-table-column><el-table-column label="实际可访问门店" min-width="300"><template #default="{row}">{{row.stores.map(s=>s.store_name).join('、')||'无可访问门店'}}</template></el-table-column><el-table-column label="岗位来源" min-width="140"><template #default="{row}">{{rightsSources(row)}}</template></el-table-column></el-table>
    </section>
    <section v-else v-loading="reportLoading"><el-table :data="logs" empty-text="暂无变更记录"><el-table-column label="时间" min-width="155"><template #default="{row}">{{formatTime(row.created_at)}}</template></el-table-column><el-table-column prop="actor_name" label="操作人" width="110"/><el-table-column prop="reason" label="原因" min-width="180"/><el-table-column type="expand"><template #default="{row}"><div class="audit-diff"><strong>调整前</strong><p>{{auditLabel(row.before_json)}}</p><strong>调整后</strong><p>{{auditLabel(row.after_json)}}</p></div></template></el-table-column></el-table></section>
   </template>
   <template #footer><div class="drawer-footer"><el-button :disabled="saving" @click="closeDetail(()=>detailOpen=false)">关闭</el-button><el-button v-if="detailTab==='profile'" type="primary" :loading="saving" @click="saveProfile">保存账号资料</el-button><el-button v-if="detailTab==='roles'" type="primary" :loading="saving" @click="saveRoles">保存岗位与门店</el-button></div></template>
  </el-drawer>

  <el-drawer v-model="creating" size="min(820px,96vw)" :close-on-click-modal="false" :before-close="closeCreate" title="新增人员">
   <el-steps :active="createStep" simple><el-step title="身份与登录"/><el-step title="岗位与门店"/><el-step title="核对创建"/></el-steps>
   <el-alert v-if="createError" :title="createError" type="error" :closable="false"/>
   <el-form v-if="createStep===0" label-position="top" class="create-form">
    <el-form-item label="人员身份" required><el-radio-group v-model="identityType" @change="newForm.employee_id=null"><el-radio value="employee">关联已有员工档案</el-radio><el-radio value="standalone">无员工档案账号</el-radio></el-radio-group></el-form-item>
    <el-form-item v-if="identityType==='employee'" label="员工档案" required><el-select v-model="newForm.employee_id" filterable placeholder="选择尚未关联账号的员工" @change="fillEmployeeName"><el-option v-for="e in data.employees" :key="e.id" :value="e.id" :disabled="!!e.linked_user_id" :label="employeeLabel(e)"/></el-select><p class="secondary">已有账号的员工不重复创建。<router-link v-if="canOpenStaff" to="/staff-management/employees">前往员工管理建档</router-link></p></el-form-item>
    <el-form-item label="显示名称" required><el-input v-model.trim="newForm.display_name" maxlength="30" placeholder="人员姓名或账号显示名称"/></el-form-item>
    <el-form-item label="登录账号" required><el-input v-model.trim="newForm.username" maxlength="50" placeholder="设置唯一登录账号" autocomplete="off"/></el-form-item>
    <el-form-item label="允许登录端" required><el-checkbox-group v-model="newForm.channels"><el-checkbox value="web">网页</el-checkbox><el-checkbox value="mini">小程序</el-checkbox></el-checkbox-group></el-form-item>
    <el-form-item v-if="newForm.channels.includes('web')" label="网页初始密码" required><el-input v-model="newForm.password" type="password" show-password autocomplete="new-password" placeholder="至少6位"/></el-form-item>
   </el-form>
   <PersonnelRoleEditor v-else-if="createStep===1" v-model="newForm" :data="data" class="create-form"/>
   <section v-else class="confirmation"><h3>{{newForm.display_name}}</h3><p>{{newForm.username}} · {{newForm.channels.map(channelLabel).join('、')}}</p><p class="secondary">{{newForm.employee_id?data.employees.find(e=>e.id===newForm.employee_id)?.name+' · 已关联员工档案':'无员工档案账号'}}</p><div v-for="(result,c) in createPreview" :key="c" class="preview-block"><strong>{{channelLabel(c)}}实际范围</strong><p v-for="a in result.assignments" :key="a.position_id">{{a.name}} <span class="secondary">{{a.is_primary?'主岗位':'兼任'}} · {{a.stores.map(s=>s.store_name).join('、')||'此端无可访问门店'}}</span></p><el-collapse v-if="result.permissions.length"><el-collapse-item :title="'查看'+result.permissions.length+'项功能权限'" name="codes"><p v-for="p in result.permissions" :key="p.code" class="secondary">{{permissionLabel(p.code)}}：{{p.stores.map(s=>s.store_name).join('、')||'无可访问门店'}}</p></el-collapse-item></el-collapse></div><p>创建原因：{{newForm.reason}}</p></section>
   <template #footer><div class="drawer-footer"><el-button :disabled="saving" @click="closeCreate(()=>creating=false)">取消</el-button><el-button v-if="createStep>0" :disabled="saving" @click="createStep--;createError=''">上一步</el-button><el-button v-if="createStep<2" type="primary" :loading="previewLoading" @click="nextCreate">下一步</el-button><el-button v-else type="primary" :loading="saving" @click="submitCreate">确认创建</el-button></div></template>
  </el-drawer>
  <el-dialog v-model="passwordOpen" title="修改网页密码" width="min(460px,94vw)" :close-on-click-modal="false"><el-form label-position="top"><el-form-item label="新密码" required><el-input v-model="passwordForm.password" type="password" show-password autocomplete="new-password"/></el-form-item><el-form-item label="确认新密码" required><el-input v-model="passwordForm.confirm" type="password" show-password autocomplete="new-password"/></el-form-item></el-form><template #footer><el-button @click="passwordOpen=false">取消</el-button><el-button type="primary" :loading="saving" @click="savePassword">保存密码</el-button></template></el-dialog>
  <el-dialog v-model="scopeOpen" title="岗位负责门店" width="min(620px,94vw)"><h3>{{scopeTitle}}</h3><p v-for="s in scopeStores" :key="s.id">{{s.store_name}}</p><el-empty v-if="!scopeStores.length" description="无可访问门店" :image-size="60"/></el-dialog>
  <el-dialog v-model="reverseOpen" title="按门店查人员" width="min(700px,94vw)"><div class="reverse-form"><el-select v-model="reverseStore" filterable placeholder="选择门店"><el-option v-for="s in data.stores" :key="s.id" :value="s.id" :label="s.store_name"/></el-select><el-select v-model="reverseCode" filterable placeholder="选择功能"><el-option v-for="p in permissionOptions" :key="p" :value="p" :label="permissionLabel(p)"/></el-select><el-radio-group v-model="reverseChannel"><el-radio value="web">网页</el-radio><el-radio value="mini">小程序</el-radio></el-radio-group><el-button :loading="reverseLoading" @click="queryMembers">查询</el-button></div><el-alert v-if="reverseError" type="error" :title="reverseError" :closable="false"/><p class="secondary">查询已完成逐岗位配置的人员；旧账号请先核对配置。修改条件后需重新查询。</p><el-table :data="members"><el-table-column prop="display_name" label="具有该功能权限的人员"/></el-table></el-dialog>
 </main>
</template>
<script setup>
import {computed,onMounted,reactive,ref,watch,nextTick} from 'vue'
import {useRouter} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import {useAuthStore} from '@/stores/auth'
import {personnelAccessApi as api,getUsers,getWechatBindings,reviewWechatBinding,updateUser,updateUserPassword,deleteUser,uploadUserAvatar,deleteUserAvatar} from '@/api'
import PersonnelRoleEditor from './PersonnelRoleEditor.vue'
import StoreRegionSelect from './StoreRegionSelect.vue'
const auth=useAuthStore(),router=useRouter(),data=reactive({users:[],positions:[],employees:[],stores:[],regions:[]})
const loading=ref(false),loadError=ref(''),pageTab=ref('people'),bindings=ref([]),bindingFilter=ref('pending'),bindingTargets=reactive({}),busyBinding=ref(null),catalog=ref([])
const emptyFilters=()=>({q:'',role:null,stores:[],channel:'all',state:'all'}),draft=reactive(emptyFilters()),applied=ref(emptyFilters()),page=ref(1),pageSize=15,highlightId=ref(null),createdNotice=ref('')
const clone=v=>JSON.parse(JSON.stringify(v)),personById=id=>data.users.find(u=>u.id===Number(id)),position=id=>data.positions.find(p=>p.id===id),employee=u=>data.employees.find(e=>e.id===u.employee_id),canOpenStaff=computed(()=>auth.can('staff.view')||auth.can('staff.store.edit'))
const channelLabel=c=>c==='web'?'网页':'小程序',channels=u=>u.access?.channels||['web','mini']
function assignments(u){return [...(u.access?.assignments||(u.position_ids||[]).map(id=>({position_id:id,is_primary:id===u.position_id,mode:u.store_id?'stores':'all',store_ids:u.store_id?[u.store_id]:[],region_ids:[]})))].sort((a,b)=>Number(b.is_primary)-Number(a.is_primary))}
function scopeIds(rule){if(rule.mode==='all')return data.stores.map(s=>s.id);if(rule.mode==='stores')return rule.store_ids||[];return [...new Set((rule.region_ids||[]).flatMap(id=>data.regions.find(r=>r.id===id)?.store_ids||[]))]}
function actualStores(a){const p=position(a.position_id);return p?.enabled?data.stores.filter(s=>scopeIds(a).includes(s.id)&&scopeIds(p).includes(s.id)):[]}
function compactScope(a){const n=actualStores(a);return n.length===1?n[0].store_name:n.length?n.length+'家门店':'无可访问门店'}
const ready=u=>!!u.access&&assignments(u).every(a=>position(a.position_id)?.channel_permissions)
const bound=u=>typeof u.wechat_bound==='boolean'?u.wechat_bound:bindings.value.some(b=>b.user_id===u.id&&b.status==='approved')
const filtered=computed(()=>data.users.filter(u=>{const f=applied.value,rows=assignments(u),chs=channels(u);return (!f.q||[u.display_name,u.username,u.phone,employee(u)?.name].some(v=>String(v||'').toLowerCase().includes(f.q.toLowerCase())))&&(!f.role||rows.some(a=>a.position_id===f.role))&&(!f.stores.length||rows.some(a=>actualStores(a).some(s=>f.stores.includes(s.id))))&&(f.channel==='all'||f.channel==='both'&&chs.includes('web')&&chs.includes('mini')||chs.includes(f.channel))&&(f.state==='all'||(f.state==='ready')===ready(u))}))
const paged=computed(()=>filtered.value.slice((page.value-1)*pageSize,page.value*pageSize)),filtersChanged=computed(()=>JSON.stringify(draft)!==JSON.stringify(applied.value))
function query(){applied.value=clone(draft);page.value=1;createdNotice.value=''}
function reset(){Object.assign(draft,emptyFilters());query()}
const pendingCount=computed(()=>bindings.value.filter(b=>b.status==='pending').length),visibleBindings=computed(()=>bindings.value.filter(b=>bindingFilter.value==='all'||b.status==='pending'))
const bindingLabels={pending:'待处理',approved:'已绑定',rejected:'已拒绝',revoked:'已解除'}
async function load(){loading.value=true;loadError.value='';try{if(auth.isAdmin){const [d,c,b]=await Promise.all([api.config(),api.catalog(),getWechatBindings()]);Object.assign(data,d);catalog.value=Object.values(c.channels).flatMap(gs=>gs.flatMap(g=>g.modules.flatMap(m=>m.items.map(i=>({key:i.key,label:m.label===i.label?m.label:m.label+' · '+i.label})))));bindings.value=b.requests||[]}else{const [list,b]=await Promise.all([getUsers(),getWechatBindings()]);data.users=list.users;data.positions=[...new Map(list.users.flatMap(u=>(u.position_ids||[]).map((id,i)=>[id,{id,name:u.position_names?.[i]||u.position_name,enabled:true,mode:'all',channels:['web','mini']}]))).values()];bindings.value=b.requests||[]}page.value=Math.max(1,Math.min(page.value,Math.ceil(filtered.value.length/pageSize)||1));return true}catch(e){loadError.value='加载失败：'+e.message;return false}finally{loading.value=false}}
async function loadBindings(){try{bindings.value=(await getWechatBindings()).requests||[]}catch(e){ElMessage.error(e.message)}}
async function reviewBinding(row,action){const u=personById(bindingTargets[row.id]);const text=action==='approve'?`确认已核实申请编号 ${row.verification}，绑定到 ${u?.display_name||u?.username}（${u?.username}）？`:action==='reject'?'确认拒绝这条微信绑定申请？':'确认解除绑定？已登录的微信会话也会失效。';try{await ElMessageBox.confirm(text,'微信绑定审核',{type:'warning'});busyBinding.value=row.id;await reviewWechatBinding(row.id,{action,user_id:bindingTargets[row.id]});await load();ElMessage.success('已处理')}catch(e){if(!['cancel','close'].includes(e))ElMessage.error(e.message)}finally{busyBinding.value=null}}
const detailOpen=ref(false),selectedId=ref(null),selected=computed(()=>personById(selectedId.value)),detailTab=ref('profile'),saving=ref(false),detailError=ref(''),profileForm=ref({}),roleForm=ref({}),profileInitial=ref(''),roleInitial=ref(''),rolePreview=ref(null),roleFingerprint=ref(''),createFingerprint=ref('')
function roleDraft(u){return {channels:[...channels(u)],employee_id:u.employee_id||null,assignments:clone(assignments(u)),version:u.access?.version||0,reason:''}}
async function openDetail(u,tab='profile'){if(!u)return;selectedId.value=u.id;profileForm.value={username:u.username,display_name:u.display_name,phone:u.phone||'',profile_version:u.profile_version};roleForm.value=roleDraft(u);profileInitial.value=JSON.stringify(profileForm.value);roleInitial.value=JSON.stringify(roleForm.value);detailError.value='';rolePreview.value=null;report.value={permissions:[]};logs.value=[];detailTab.value=tab;detailOpen.value=true;if(tab==='rights'||tab==='history')await loadDetailData()}
const dirty=computed(()=>detailTab.value==='profile'?JSON.stringify(profileForm.value)!==profileInitial.value:detailTab.value==='roles'?JSON.stringify(roleForm.value)!==roleInitial.value:false)
async function discard(){if(!dirty.value)return true;try{await ElMessageBox.confirm('有未保存的修改，确认放弃？','离开编辑',{confirmButtonText:'放弃修改',cancelButtonText:'继续编辑',type:'warning'});return true}catch{return false}}
async function closeDetail(done){if(!saving.value&&await discard())done()}
async function leaveDetailTab(){if(saving.value)return false;const ok=await discard();if(ok&&dirty.value){const u=selected.value;profileForm.value={username:u.username,display_name:u.display_name,phone:u.phone||'',profile_version:u.profile_version};roleForm.value=roleDraft(u);rolePreview.value=null}detailError.value='';return ok}
function openStaff(u){const e=employee(u);if(e)router.push({path:'/staff-management/employees',query:{employee_name:e.name,employment_status:e.status}})}
function employeeLabel(e){return `${e.name} · ${e.store_name||'未登记归属'} · ${e.position||''}${e.linked_user_id?'（已有账号）':''}`}
async function goBindings(){await closeDetail(()=>{detailOpen.value=false;pageTab.value='bindings';bindingFilter.value='all'})}
async function saveProfile(){if(saving.value)return;detailError.value='';saving.value=true;try{if(auth.isAdmin)await api.profile(selectedId.value,profileForm.value);else{const {profile_version,...payload}=profileForm.value;await updateUser(selectedId.value,payload)}if(!await load()){detailError.value='账号资料已保存，列表刷新失败，请重新加载';return}await openDetail(personById(selectedId.value),'profile');ElMessage.success('账号资料已保存')}catch(e){detailError.value=e.message}finally{saving.value=false}}
async function saveRoles(){if(saving.value)return;if(!roleForm.value.reason.trim()){detailError.value='请填写调整原因';return}detailError.value='';saving.value=true;try{await api.save(selectedId.value,{...roleForm.value,review_fingerprint:roleFingerprint.value||undefined});if(!await load()){detailError.value='岗位配置已保存，列表刷新失败，请重新加载';return}await openDetail(personById(selectedId.value),'roles');ElMessage.success('岗位与门店已保存')}catch(e){detailError.value=e.message}finally{saving.value=false}}
const previewLoading=ref(false)
async function previewRoles(isNew){previewLoading.value=true;try{const f=isNew?newForm.value:roleForm.value;const r=await api.preview({...f,user_id:isNew?0:selectedId.value,password:undefined});if(isNew){createPreview.value=r.preview;createFingerprint.value=r.review_fingerprint}else{rolePreview.value=r.preview;roleFingerprint.value=r.review_fingerprint}return true}catch(e){if(isNew)createError.value=e.message;else detailError.value=e.message;return false}finally{previewLoading.value=false}}
watch(roleForm,()=>{rolePreview.value=null;roleFingerprint.value=''}, {deep:true})
const reportChannel=ref('web'),report=ref({permissions:[]}),logs=ref([]),reportLoading=ref(false),rightQuery=ref(''),rightStore=ref(null);let reportRequest=0
watch([detailTab,reportChannel],()=>{if(detailOpen.value)loadDetailData()})
async function loadDetailData(){if(!auth.isAdmin||!selected.value||!['rights','history'].includes(detailTab.value))return;const request=++reportRequest,id=selectedId.value,tab=detailTab.value,c=reportChannel.value;reportLoading.value=true;detailError.value='';try{const result=tab==='rights'?await api.report(id,c):await api.logs(id);if(request!==reportRequest||id!==selectedId.value)return;if(tab==='rights')report.value=result;else logs.value=result.rows||[]}catch(e){if(request===reportRequest)detailError.value=e.message}finally{if(request===reportRequest)reportLoading.value=false}}
const permissionLabel=code=>code==='*'?'全部功能':code==='store-manager.identity'?'正式店长职责':catalog.value.find(p=>p.key===code)?.label||code
const visibleRights=computed(()=>(report.value.permissions||[]).filter(p=>!rightQuery.value||permissionLabel(p.code).includes(rightQuery.value)||p.code.includes(rightQuery.value)))
function rightsSources(row){return (row.sources||(report.value.assignments||[]).filter(a=>position(a.position_id)?.permissions?.some(p=>p===row.code||p==='*'))).map(a=>a.name||position(a.position_id)?.name).join('、')||'兼容配置'}
