async function nextCreate(){createError.value='';if(createStep.value===0){const f=newForm.value;if(identityType.value==='employee'&&!f.employee_id){createError.value='请选择员工档案，或选择无员工档案账号';return}if(!f.display_name||!f.username){createError.value='请填写显示名称和登录账号';return}if(!f.channels.length){createError.value='请选择允许登录端';return}if(f.channels.includes('web')&&f.password.length<6){createError.value='网页初始密码至少6位';return}createStep.value=1}else{if(!newForm.value.reason.trim()){createError.value='请填写新增原因';return}if(await previewRoles(true))createStep.value=2}}
